1	#!/usr/bin/env bun
2	/**
3	 * claim_turn.ts — claim the turn: which run took up which ask (#285).
4	 *
5	 * The runner writes one comment at start —
6	 *
7	 *     <!-- atomaton:llm-context=exclude -->
8	 *     <!-- atomaton:took=<ask comment id> run=<run id> -->
9	 *
10	 * — and that comment is the turn's identity from the taking side. The run watch
11	 * compares it against the endings by run id ("did THIS run take a turn", "did THIS
12	 * run report"), and the guard's shaping reads it as the ball being with an agent.
13	 * What the claim replaces is estimation: a marker or a command inside a run's
14	 * lifetime used to be attributed by timestamp, and two runs close together were
15	 * attributed to the wrong one — #281's both halves.
16	 *
17	 * ## The race, and why it cannot happen here
18	 *
19	 * Two runs reaching for one ask is a dispatch-level failure (the ordering check or
20	 * the ask check should have stopped the second dispatch), so this is defence in
21	 * depth — but it is depth that cannot itself race, because the runner runs under
22	 * `atomaton-<type>-<number>` concurrency with `cancel-in-progress: false`: two runs
23	 * on one node are serialised, so the second claims only after the first has
24	 * finished. The check still runs, because queues are exactly when identity
25	 * mistakes are made: post the claim, wait until the listing shows it (GitHub does
26	 * not guarantee read-after-write — the same instrument `postDispatchMarker` runs),
27	 * then read the thread again and look for ANOTHER claim on the same ask with a
28	 * smaller comment id. Found one, this run backs off: it deletes its own claim and
29	 * writes `claimed=false`, and the workflow steps that would take the turn are
30	 * gated off it. The other run — its claim is older — holds the turn, and a backed
31	 * off run leaves no ending, because it took no turn the thread names.
32	 *
33	 * ## The exit code
34	 *
35	 * A claim GitHub refused is a machinery failure and exits non-zero: the run would
36	 * otherwise work without its identity on the thread, which is the state every
37	 * later comparison misreads. A backed-off claim is `0` — the back-off is the
38	 * correct outcome, not a fault — and the job goes green having done nothing,
39	 * which is what losing a race looks like.
40	 *
41	 * Usage:
42	 *   claim_turn.ts --number N --ask ID --run-id ID [--repo R]
43	 * Writes `claimed=true|false` to $GITHUB_OUTPUT.
44	 */
45	import { parseArgs } from "node:util";
46	import { gh, ghRead, splitConcatenatedJson } from "../../adapters/github/gh.ts";
47	import { LLM_CONTEXT_TAG, TOOK_TAG } from "../../adapters/github/tags.ts";
48	import { defineScript } from "./lib/script-ref.ts";
49	
50	export interface ClaimTurnArgs {
51	  number: string | number;
52	  /** The ask comment id this run takes up; empty for a run whose ask is the body. */
53	  ask?: string;
54	  "run-id"?: string;
55	  repo?: string;
56	}
57	
58	export const ref = defineScript<ClaimTurnArgs>(import.meta.url);
59	
60	/** Delays between reads while waiting for the listing to show the claim. */
61	const READ_DELAYS_MS = [1_000, 2_000, 4_000];
62	
63	/** Every comment on the node, oldest first, as the race check reads them. */
64	function listBodies(repo: string, number: number): { id: number; body: string }[] {
65	  const listed = ghRead("api", `repos/${repo}/issues/${number}/comments`, "--paginate", "--jq", ".");
66	  if (listed.code !== 0) throw new Error(`could not read #${number}'s comments: ${listed.stderr || listed.stdout}`);
67	  const comments: { id: number; body: string }[] = [];
68	  for (const page of splitConcatenatedJson(listed.stdout || "[]")) {
69	    if (!Array.isArray(page)) continue;
70	    for (const entry of page as { id?: number; body?: string }[]) {
71	      if (typeof entry.id === "number") comments.push({ id: entry.id, body: entry.body ?? "" });
72	    }
73	  }
74	  return comments;
75	}
76	
77	export function claimCommentBody(args: { ask: number; run: number }): string {
78	  return [LLM_CONTEXT_TAG.write("exclude"), TOOK_TAG.write(args)].join("\n");
79	}
80	
81	/**
82	 * Whether this run holds the turn for its ask: the claim is posted, visible, and
83	 * no older claim on the same ask exists.
84	 *
85	 * Split out of `main` so the read-after-write and the id comparison are testable
86	 * without GitHub: the caller hands in the comments as they stand and the id the
87	 * run's own claim carries.
88	 */
89	export function raceOutcome(
90	  comments: readonly { id: number; body: string }[],
91	  mine: { id: number; ask: number },
92	): "held" | "backed-off" {
93	  for (const comment of comments) {
94	    if (comment.id >= mine.id) break; // oldest first; nothing newer can have claimed first
95	    // Prose only: a comment quoting a took tag in a fenced sample has not claimed
96	    // anything (#304).
97	    const claim = TOOK_TAG.readProse(comment.body);
98	    if (claim !== undefined && claim.ask === mine.ask) return "backed-off";
99	  }
100	  return "held";
101	}
102	
103	async function main(): Promise<void> {
104	  const { values } = parseArgs({
105	    args: Bun.argv.slice(2),
106	    options: {
107	      number: { type: "string" },
108	      ask: { type: "string" },
109	      "run-id": { type: "string" },
110	      repo: { type: "string" },
111	    },
112	  });
113	
114	  const repo = values.repo ?? process.env.GITHUB_REPOSITORY ?? "";
115	  const number = Number(values.number);
116	  const runId = Number(values["run-id"] ?? process.env.GITHUB_RUN_ID ?? 0);
117	  const ask = Number(values.ask ?? 0) || 0;
118	
119	  const record = (claimed: boolean): void => {
120	    const out = process.env.GITHUB_OUTPUT;
121	    if (out) {
122	      const { appendFileSync } = require("node:fs") as typeof import("node:fs");
123	      appendFileSync(out, `claimed=${claimed ? "true" : "false"}\n`);
124	    }
125	    console.error(`claim_turn: claimed=${claimed ? "true" : "false"} (ask=${ask}, run=${runId})`);
126	  };
127	
128	  // No ask comment to claim: a run started by a new issue's body, or by anything
129	  // else that is not a comment. It takes no turn the thread can name, writes no
130	  // claim, and the watch stays silent on it — the honest shape of "the body is
131	  // not an ask".
132	  if (!Number.isInteger(number) || number <= 0) throw new Error("--number must be a positive number");
133	  if (ask <= 0) {
134	    record(true);
135	    return;
136	  }
137	  if (!Number.isInteger(runId) || runId <= 0) throw new Error("--run-id must be a positive number");
138	
139	  const posted = gh("api", `repos/${repo}/issues/${number}/comments`, "--method", "POST", "-f", `body=${claimCommentBody({ ask, run: runId })}`, "--jq", ".id");
140	  if (posted.code !== 0) throw new Error(`could not post the claim on #${number}: ${posted.stderr || posted.stdout}`);
141	  const claimId = Number(posted.stdout.trim());
142	  if (!Number.isInteger(claimId) || claimId <= 0) throw new Error(`the claim's id came back unreadable: ${posted.stdout.trim()}`);
143	
144	  // GitHub does not guarantee read-after-write. Until the listing shows THIS
145	  // comment, the read may still predate it, and a race judged on that read would
146	  // judge a thread that has not caught up — the same instrument the dispatch
147	  // marker runs before its ordering check is trusted.
148	  let visible = false;
149	  for (let attempt = 0; attempt <= READ_DELAYS_MS.length; attempt += 1) {
150	    if (listBodies(repo, number).some((comment) => comment.id === claimId)) {
151	      visible = true;
152	      break;
153	    }
154	    const delay = READ_DELAYS_MS[attempt];
155	    if (delay === undefined) break;
156	    await Bun.sleep(delay);
157	  }
158	  if (!visible) throw new Error(`the claim on #${number} never became visible, so the race check cannot be trusted`);
159	
160	  const outcome = raceOutcome(listBodies(repo, number), { id: claimId, ask });
161	  if (outcome === "held") {
162	    record(true);
163	    return;
164	  }
165	

