1	import { describe, expect, test } from "bun:test";
2	import {
3	  askUnanswered,
4	  endingLeftBy,
5	  lastEndingComment,
6	  parseRunTitle,
7	  releasesLabel,
8	  turnClaimedBy,
9	  type DatedComment,
10	} from "./run-report.ts";
11	import { endingWalkReaders, readers } from "../../adapters/github/thread.ts";
12	
13	/**
14	 * The run watch's judgement, asked of strings alone. The readers are the REAL
15	 * ones (`endingWalkReaders`), because the mapping under test — that `done`,
16	 * `stopped` and `limit` return the node, that `handoff` keeps it, that a guard
17	 * quotation is nobody's ending — is the mapping the thread machinery itself
18	 * uses, and a test's own copy of it would test the copy.
19	 *
20	 * #285 replaced the two time gates with the thread's own identity: the claim
21	 * (`turnClaimedBy`) and the ending (`endingLeftBy`) are compared BY RUN ID, and
22	 * `askUnanswered` is what makes the watch's notice a once-per-ask event. The
23	 * time gates' tests — the marker-inside-lifetime branches, the command fallback's
24	 * four conditions — died with them; what stands here is the comparison and the
25	 * quotation rule the walks share.
26	 */
27	
28	const START = "2026-10-22T10:00:00Z";
29	
30	function comment(body: string, createdAt: string): DatedComment {
31	  return { body, createdAt };
32	}
33	
34	function commentsWith(...bodies: string[]): DatedComment[] {
35	  // Timestamped a full day BEFORE the usual run start, unless a test names its own.
36	  return bodies.map((body, index) => comment(body, `2026-10-2${index}T09:00:00Z`));
37	}
