39	describe("parseRunTitle", () => {
40	  test("reads the runner's run-name shape", () => {
41	    expect(parseRunTitle("engineer on #252")).toEqual({ agent: "engineer", number: 252 });
42	  });
43	
44	  test("tolerates surrounding whitespace", () => {
45	    expect(parseRunTitle("  reviewer on #17 \n")).toEqual({ agent: "reviewer", number: 17 });
46	  });
47	
48	  test("reads nothing in the runner's own name, which every run carried before run-name", () => {
49	    expect(parseRunTitle("Atomaton Runner")).toBeUndefined();
50	  });
51	
52	  test("reads nothing in a title that is not this machinery's", () => {
53	    expect(parseRunTitle("deploy: apply v0.21.22 to .github/")).toBeUndefined();
54	    expect(parseRunTitle("engineer on #abc")).toBeUndefined();
55	    expect(parseRunTitle("on #252")).toBeUndefined();
56	    expect(parseRunTitle("engineer on #252 extra")).toBeUndefined();
57	    expect(parseRunTitle("")).toBeUndefined();
58	    expect(parseRunTitle(undefined)).toBeUndefined();
59	  });
60	
61	  test("reads the entry workflows' agent-less shape, which their run-name writes", () => {
62	    expect(parseRunTitle("#252")).toEqual({ agent: undefined, number: 252 });
63	  });
64	
65	  test("reads nothing in a node number that cannot exist", () => {
66	    expect(parseRunTitle("engineer on #0")).toBeUndefined();
67	    expect(parseRunTitle("engineer on #-3")).toBeUndefined();
68	    expect(parseRunTitle("#0")).toBeUndefined();
69	  });
70	});
71	
72	/**
73	 * The identity gates (#285): the claim and the ending are compared BY RUN ID — the
74	 * watch's two questions are now reads of the thread, and the tests fix the
75	 * comparisons the estimations replaced.
76	 */
77	describe("turnClaimedBy / endingLeftBy", () => {
78	  const RUN = 424242;
79	  const OTHER = 999999;
80	  const ASK = 55;
81	  const claim = (ask = ASK, run = RUN) => `<!-- atomaton:llm-context=exclude -->\n<!-- atomaton:took=${ask} run=${run} -->`;
82	  const ended = (verb: string, answers: number, run: number, agent?: string) =>
83	    [...(agent ? [`<!-- atomaton:agent=${agent} -->`] : []), `<!-- atomaton:ended=${verb} answers=${answers} run=${run} -->`].join("\n");
84	
85	  test("the claim names the ask the run took, by run id", () => {
86	    expect(turnClaimedBy(commentsWith(claim()), RUN, endingWalkReaders)).toBe(ASK);
87	    expect(turnClaimedBy(commentsWith(claim(ASK, OTHER)), RUN, endingWalkReaders)).toBeUndefined();
88	    expect(turnClaimedBy(commentsWith("just a remark"), RUN, endingWalkReaders)).toBeUndefined();
89	  });
90	
91	  test("the ending is the run's own, by run id", () => {
92	    expect(endingLeftBy(commentsWith(ended("done", ASK, RUN)), RUN, endingWalkReaders)).toBe(true);
93	    expect(endingLeftBy(commentsWith(ended("done", ASK, OTHER)), RUN, endingWalkReaders)).toBe(false);
94	    // An old-format ending does not parse, and an unreadable ending is not an
95	    // ending: the watch keeps its silence on a thread it cannot read.
96	    expect(endingLeftBy(commentsWith("<!-- atomaton:ended=done -->"), RUN, endingWalkReaders)).toBe(false);
97	  });
98	
99	  test("an ended tag inside a guard quotation is the deleted author's words, not an ending", () => {
100	    const quotation = [
101	      "<!-- atomaton:llm-context=exclude -->",
102	      "<!-- atomaton:quotes=123 -->",
103	      "Your comment was removed because a run holds the turn on this issue/PR.",
104	      "<details><summary>Your comment, as you wrote it</summary>",
105	      "",
106	      "```",
107	      ended("done", ASK, RUN),
108	      "```",
109	      "",
110	      "</details>",
111	    ].join("\n");
112	    // The quotation carries the watched run's own ids — a walk that read it would
113	    // excuse the run for an ending that is a deleted person's comment.
114	    expect(endingLeftBy(commentsWith(quotation), RUN, endingWalkReaders)).toBe(false);
115	    expect(turnClaimedBy(commentsWith(quotation), RUN, endingWalkReaders)).toBeUndefined();
116	    expect(lastEndingComment(commentsWith(quotation), endingWalkReaders)).toBeUndefined();
117	  });
118	
119	  test("the watch notices only the claimed-and-unanswered pair", () => {
120	    // Claimed and answered: the run reported, silence.
121	    const reported = commentsWith(claim(), ended("done", ASK, RUN));
122	    expect(turnClaimedBy(reported, RUN, endingWalkReaders)).toBe(ASK);
123	    expect(endingLeftBy(reported, RUN, endingWalkReaders)).toBe(true);
124	    // Claimed and unanswered: the notice.
125	    const dead = commentsWith(claim());
126	    expect(turnClaimedBy(dead, RUN, endingWalkReaders)).toBe(ASK);
127	    expect(endingLeftBy(dead, RUN, endingWalkReaders)).toBe(false);
128	    // Neither: no turn the thread names, silence whatever the conclusion was.
129	    expect(turnClaimedBy(commentsWith("just a remark"), RUN, endingWalkReaders)).toBeUndefined();
130	  });
131	
132	  test("the healed thread reads as answered — the notice is a once-per-ask event", () => {
133	    // The watch's notice carries `answers=<claimed ask> run=<watch id>`; after it,
134	    // the ask no longer reads as unanswered, so no later watch posts it again.
135	    const healed = commentsWith(claim(), ended("done", ASK, 9));
136	    expect(askUnanswered(healed, ASK, endingWalkReaders)).toBe(false);
137	    expect(askUnanswered(commentsWith(claim()), ASK, endingWalkReaders)).toBe(true);
138	    // An old-format ending does not parse, so it answers nothing — and the
139	    // machinery's `answers=0` matches no ask by construction.
140	    expect(askUnanswered(commentsWith("<!-- atomaton:ended=done -->"), ASK, endingWalkReaders)).toBe(true);
141	    expect(askUnanswered(commentsWith(ended("done", 0, 9)), ASK, endingWalkReaders)).toBe(true);
142	  });
143	});
144	
145	describe("releasesLabel", () => {
146	  const at = "2026-10-22T09:00:00Z";
147	
148	  test("releases on every ending that returned the node or left it waiting on a child", () => {
149	    for (const ended of ["done", "stopped", "limit", "waiting"]) {
150	      expect(releasesLabel(comment(`<!-- atomaton:ended=${ended} answers=0 run=0 -->`, at), endingWalkReaders), ended).toBe(true);
151	    }
152	  });
153	
154	  test("holds on a hand-off, the one ending that leaves the turn with an agent", () => {
155	    expect(releasesLabel(comment("<!-- atomaton:ended=handoff answers=0 run=0 -->", at), endingWalkReaders)).toBe(false);
156	  });
